//! 🧾️ Own Part21 forward and exact inverse wire sizes advance the original Store codec without value projections.
use super::*;
use semio_framework_pack_json::{ArtifactCanonicalJsonNode as Node,ArtifactCanonicalJsonText as Text,ArtifactCanonicalJsonTree as Tree};
use semio_framework_plugin::plugin_app_close_prelude::store;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value::retained_clone::{RetainedCloneSource,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use std::sync::Arc;
pub(super)type Source=RetainedCloneSource<Ifc2x3Snapshot,Arc<Ifc2x3Snapshot>>;
#[derive(Clone,Copy,Default)]enum Phase{#[default]Preflight,Locate,Forward,CloseForward,RestartForward,Inverse,CloseInverse,RestartInverse,Done}
#[derive(Clone,Copy,Default)]enum Inverse{#[default]None,Upsert,Insert,Remove,Header}
#[derive(Default)]pub(super)struct View{pub source:Option<Source>,inverse:Inverse,id:u64,found:Option<usize>}
pub(super)struct Publication{pub view:View,codec:store::ArtifactPreparedOperationCursor,phase:Phase,row:usize,identity:Option<(usize,usize)>,bytes:usize,chunk:[u8;64]}
impl Default for Publication{fn default()->Self{Self{view:Default::default(),codec:Default::default(),phase:Default::default(),row:0,identity:None,bytes:0,chunk:[0;64]}}}
fn error()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"Own Part21 publication requires its captured single mutation and exact inverse")}
fn receipt(progress:store::ArtifactPreparedOperationProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:progress.processed_items,copied_bytes:progress.copied_bytes,retained_capacity_bytes:progress.retained_capacity_bytes,released_bytes:progress.released_bytes}}
impl View{
 fn snapshot(&self)->Result<&Ifc2x3Snapshot,ValueError>{Ok(self.source.as_ref().ok_or_else(error)?.try_authority()?.as_ref())}
 fn fields(&self)->&'static[&'static str]{match self.inverse{Inverse::None=>&[],Inverse::Remove=>&["id"],Inverse::Header=>&["header"],Inverse::Upsert=>&["instance"],Inverse::Insert=>&["instance","index"]}}
 fn tag(&self)->&'static str{match self.inverse{Inverse::None=>"",Inverse::Remove=>"removeInstance",Inverse::Header=>"setHeader",Inverse::Upsert|Inverse::Insert=>"upsertInstance"}}
 fn child(&self,index:usize)->Result<&dyn Tree,ValueError>{match(self.inverse,index){(Inverse::Remove,0)=>Ok(&self.id),(Inverse::Header,0)=>Ok(&self.snapshot()?.document.header),(Inverse::Upsert|Inverse::Insert,0)=>Ok(self.snapshot()?.document.instances.get(self.found.ok_or_else(error)?).ok_or_else(error)?),(Inverse::Insert,1)=>self.found.as_ref().map(|row|row as &dyn Tree).ok_or_else(error),_=>Err(error())}}
 fn descendant(&self,path:&[usize])->Result<&dyn Tree,ValueError>{let(first,rest)=path.split_first().ok_or_else(error)?;let mut child=self.child(first.checked_sub(1).ok_or_else(error)?)?;for index in rest{child=child.canonical_tree_child(*index)?;}Ok(child)}
}
impl Publication{
 fn snapshot(&self)->Result<&Ifc2x3Snapshot,ValueError>{self.view.snapshot()}
 pub(super)fn demands(&self)->Result<RetirementDemand,ValueError>{match self.phase{Phase::Forward|Phase::Inverse=>self.codec.canonical_json_work_demands(),Phase::CloseForward|Phase::CloseInverse=>self.codec.retirement_demands(),Phase::RestartForward|Phase::RestartInverse=>Ok(self.codec.canonical_json_restart_demands()),_=>Ok(RetirementDemand{copy_bytes:4*std::mem::size_of::<usize>(),depth:1,..Default::default()})}}
 fn counted(&mut self,written:usize)->Result<(),ValueError>{self.bytes=self.bytes.checked_add(written).ok_or_else(error)?;if self.bytes>protocol::os_store::one_item::ARTIFACT_STORE_ONE_ITEM_MAXIMUM_BYTES{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"Own Part21 mutation or exact inverse exceeds the native item byte limit"));}Ok(())}
 pub(super)fn advance(&mut self,mutations:&[Ifc2x3Mutation],capacity:semio_framework_plugin::retained_command::ArtifactRetainedWorkCapacity,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,semio_framework_job::OriginalTurnFailure>{if cx.is_cancelled(){return Err(err("details-cancelled").into());}if cx.should_yield(){return Ok(false);}if self.identity.is_some_and(|identity|identity!=(mutations.as_ptr()as usize,mutations.len())){return Err(error().into());}let demand=self.demands()?;let grant=cx.retained_grant();if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,demand){return Ok(false);}match self.phase{
 Phase::Preflight=>{if mutations.len()>1{return Err(error().into());}self.identity=Some((mutations.as_ptr()as usize,mutations.len()));let Some(mutation)=mutations.first()else{self.phase=Phase::Done;cx.consume_fuel(1);return Ok(true)};let rows=1usize.checked_add(<Ifc2x3Mutation as protocol::Mutation<Ifc2x3Snapshot>>::inverse_rows(mutation)).ok_or_else(error)?;if !capacity.admits(rows){return Err(error().into());}match mutation{Ifc2x3Mutation::UpsertInstance(change)=>{self.view.id=change.instance.id;self.view.inverse=Inverse::Upsert;self.phase=Phase::Locate;},Ifc2x3Mutation::RemoveInstance(change)=>{self.view.id=change.id;self.view.inverse=Inverse::Insert;self.phase=Phase::Locate;},Ifc2x3Mutation::SetHeader(_)=>{self.view.inverse=Inverse::Header;self.phase=Phase::Forward;}}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})?;}
 Phase::Locate=>{let length=self.snapshot()?.document.instances.len();if self.row==length{if self.view.found.is_none(){self.view.inverse=if matches!(self.view.inverse,Inverse::Upsert){Inverse::Remove}else{Inverse::None};}self.bytes=0;self.phase=Phase::Forward;}else{if self.snapshot()?.document.instances[self.row].id==self.view.id{if self.view.found.is_some(){return Err(error().into());}self.view.found=Some(self.row);}self.row+=1;}}
 Phase::Forward|Phase::Inverse=>{let progress=if matches!(self.phase,Phase::Forward){self.codec.advance(store::ArtifactPreparedOperationSource::CanonicalJson{header:b"op",body:store::ArtifactCanonicalTreeSource::view(&mutations[0])},&mut self.chunk,grant)}else{let inverse=InverseView{publication:&self.view};let mut chunk=[0;64];let result=self.codec.advance(store::ArtifactPreparedOperationSource::CanonicalJson{header:b"op",body:&inverse},&mut chunk,grant);result};match progress{Ok(progress)=>{let complete=progress.complete;let written=progress.written_bytes;cx.consume_retained(receipt(progress))?;self.counted(written)?;if complete{self.phase=if matches!(self.phase,Phase::Forward){Phase::CloseForward}else{Phase::CloseInverse};}},Err(error)=>{cx.consume_retained(error.reason.retained_progress())?;return Err(error.reason.into());}}}
 Phase::CloseForward|Phase::CloseInverse=>{let progress=self.codec.close(grant).map_err(|error|semio_framework_job::OriginalTurnFailure::debit_original(error.reason,cx))?;let complete=progress.complete;cx.consume_retained(receipt(progress))?;if complete{self.phase=if matches!(self.phase,Phase::CloseForward){Phase::RestartForward}else{Phase::RestartInverse};}}
 Phase::RestartForward|Phase::RestartInverse=>{let Some(progress)=self.codec.restart_canonical_json(grant)?else{return Ok(false)};cx.consume_retained(progress)?;if matches!(self.phase,Phase::RestartForward)&&!matches!(self.view.inverse,Inverse::None){self.bytes=0;self.phase=Phase::Inverse;}else{self.phase=Phase::Done;}}
 Phase::Done=>return Ok(true),
 }cx.consume_fuel(1);Ok(matches!(self.phase,Phase::Done))}
 pub(super)fn codec_live(&self)->bool{!self.codec.closed}
 pub(super)fn close_demands(&self)->Result<RetirementDemand,ValueError>{self.codec.retirement_demands()}
 pub(super)fn close_codec(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let progress=self.codec.close(grant).map_err(|error|error.reason)?;let complete=progress.complete;let progress=receipt(progress);Ok(if complete{RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)})}
}
struct InverseView<'a>{publication:&'a View}
impl store::ArtifactCanonicalJson for InverseView<'_>{fn canonical_json_original_owner(&self)->Option<&dyn store::ArtifactCanonicalJson>{Some(self.publication)}fn canonical_json_node(&self,path:&[usize])->Result<Node<'_>,ValueError>{store::ArtifactCanonicalJson::canonical_json_node(self.publication,path)}fn canonical_json_key(&self,path:&[usize],index:usize)->Result<Text<'_>,ValueError>{store::ArtifactCanonicalJson::canonical_json_key(self.publication,path,index)}}
impl store::ArtifactCanonicalJson for View{fn canonical_json_node(&self,path:&[usize])->Result<Node<'_>,ValueError>{match path{[]=>Ok(Node::Object(self.fields().len()+1)),[0]=>Ok(Node::String(self.tag())),_=>self.descendant(path)?.canonical_tree_node()}}fn canonical_json_key(&self,path:&[usize],index:usize)->Result<Text<'_>,ValueError>{if path.is_empty(){if index==0{return Ok("mutation".into());}return self.fields().get(index-1).map(|key|Text::from(*key)).ok_or_else(error);}self.descendant(path)?.canonical_tree_key(index)}}

